  "stuSess.penaltyChoiceRefund": "Povrat na izvorni način plaćanja",
  "stuSess.penaltyChoiceRefundDesc": "Za povrat novca (€{amount}) obrati se na info@tutlio.lt. Ako je plaćeno karticom, povrat se ipak može automatski pokrenuti putem Stripea.",
  "stuSess.creditAvailable": "Raspoloživ kredit",
  "stuSess.payWithCredit": "Plati kreditom",
  "stuSess.creditAppliedSuccess": "Kredit od €{amount} dodan je tvojem saldu i automatski će se primijeniti na sljedeći sat.",
  "stuSess.refundContactNote": "Za povrat novca obrati se na <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Imaš pitanja ili poteškoća? Obrati se na <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Tvoj povrat novca pokrenut je putem Stripea.</p><p class=\"text-emerald-800 mt-1\">Povrat na karticu obično stiže u roku od približno <strong>5–10 radnih dana</strong> (ovisno o banci). Ako ne stigne u uobičajenom roku, piši na <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Čini se da ovaj sat nije plaćen putem Stripea na platformi Tutlio (npr. bankovnim prijenosom ili gotovinom). Ovdje nema automatskog povrata novca.</p><p class=\"mt-2\">Za dogovor o povratu obrati se svojem instruktoru: <strong>{tutor}</strong> — koristi e-poštu ili kontaktne podatke iz rezervacije ili one koje ti je instruktor izravno dao.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Čini se da ovaj sat nije plaćen putem Stripea na platformi Tutlio (npr. bankovnim prijenosom ili gotovinom). Ovdje nema automatskog povrata novca.</p><p class=\"mt-2\">Budući da pohađaš satove putem organizacije, obrati se <strong>administratoru organizacije</strong> (putem instruktora ili javno objavljenih kontakata organizacije).</p>",
  "stuSess.refundTutorFallback": "tvoj instruktor",
