  "orgTutorPolicy.title": "Interna pravila za instruktore",
  "orgTutorPolicy.intro": "Prije korištenja platforme pročitaj interna pravila organizacije.",
  "orgTutorPolicy.acceptBtn": "Razumijem",
  "orgTutorPolicy.viewBtn": "Pogledaj interna pravila",
  "orgTutorPolicy.s1Title": "1. Opće odredbe",
  "orgTutorPolicy.s1Body": "Ova pravila uređuju tvoje korištenje platforme Tutlio („Platforma”) u svojstvu nastavnika ili instruktora („Instruktor”). Na korištenje Platforme pozvala te obrazovna agencija, škola ili centar za instrukcije koji zastupaš („Organizacija”). Tehničko održavanje i podršku Platformi pruža MB Tutlio. Korištenjem računa prihvaćaš ova Pravila i Pravila privatnosti.",
  "orgTutorPolicy.s2Title": "2. Upravljanje računom i rasporedima",
  "orgTutorPolicy.s2Intro": "Platforma je osmišljena tako da ne moraš trošiti vrijeme na dogovaranje termina satova s učenicima.",
  "orgTutorPolicy.s2Link": "Jedinstvena poveznica: dodijeljena ti je osobna poveznica za rezervaciju satova (prema predmetima koje podučavaš), putem koje učenici zakazuju satove.",
  "orgTutorPolicy.s2Calendar": "Sinkronizacija kalendara: tvoja dostupnost izravno ovisi o integraciji s Google kalendarom (2-smjerna sinkronizacija). Osobno odgovaraš za točnost i ažurnost slobodnih termina u svojem kalendaru. Platforma neće dopustiti učenicima rezervaciju vremena označenog kao zauzeto.",
  "orgTutorPolicy.s2Security": "Sigurnost računa: tvoj je račun osoban. Podatke za prijavu moraš čuvati na sigurnom i ne smiješ ih dijeliti s trećim osobama.",
  "orgTutorPolicy.s3Title": "3. Otkazivanje satova i lista čekanja",
  "orgTutorPolicy.s3Intro": "Platforma pomaže što bolje popuniti raspored i izbjeći prazne termine:",
  "orgTutorPolicy.s3Auto": "Ako učenik otkaže sat, Platforma automatski šalje obavijest (SMS/e-pošta) drugim učenicima na tvojoj listi čekanja i nudi oslobođeni termin. Ne trebaš poduzimati dodatne radnje.",
  "orgTutorPolicy.s3Rules": "Pravila otkazivanja satova (koliko unaprijed je otkazivanje dopušteno i njegove posljedice) određuje tvoja Organizacija.",
  "orgTutorPolicy.s4Title": "4. Financije i plaćanja",
  "orgTutorPolicy.s4Intro": "Ne moraš brinuti o izdavanju računa ili naplati roditeljima:",
  "orgTutorPolicy.s4Advance": "Sva plaćanja učenika (ili roditelja) za tvoje satove prikupljaju se unaprijed putem Platforme i prenose izravno tvojoj Organizaciji.",
  "orgTutorPolicy.s4Confirmed": "Sat održavaš samo kad je potvrđen u sustavu (što znači da je već naplaćen).",
  "orgTutorPolicy.s4Contact": "Za plaću, raspored isplata i ostala financijska pitanja obrati se izravno administratoru Organizacije. MB Tutlio ne provodi izravne financijske transakcije s Instruktorima.",
  "orgTutorPolicy.s5Title": "5. Zaštita podataka učenika (GDPR)",
  "orgTutorPolicy.s5Intro": "Kao Instruktor imaš pristup osobnim podacima učenika, internim bilješkama i materijalima za učenje. Obvezuješ se na:",
  "orgTutorPolicy.s5Use": "Korištenje tih podataka isključivo za organizaciju i održavanje satova.",
  "orgTutorPolicy.s5NoCopy": "Zabranu kopiranja, izvoza ili distribucije kontaktnih podataka učenika ili roditelja izvan Platforme.",
  "orgTutorPolicy.s5Notes": "Zaštitu internih zapisa Organizacije (bilješke o napretku učenika) koji su vidljivi samo tebi i administraciji Organizacije, a ne učenicima ili roditeljima.",
  "orgTutorPolicy.s5Termination": "Nakon prestanka tvojeg radnog odnosa s Organizacijom, pristup tim podacima odmah će se ukinuti.",
  "orgTutorPolicy.s6Title": "6. Tehnički rad i ograničenje odgovornosti",
  "orgTutorPolicy.s6Body": "Zabranjeno je koristiti Platformu u nezakonite svrhe, distribuirati zlonamjerne poveznice u nastavnim materijalima ili na drugi način ometati rad sustava. MB Tutlio osigurava rad i tehničko održavanje Platforme, ali ne preuzima odgovornost za smetnje uzrokovane tvojom internetskom vezom, kvarom uređaja ili pogrešnim postavkama Google kalendara.",
  "orgTutorPolicy.s7Title": "7. Podrška i kontakti",
  "orgTutorPolicy.s7Org": "Za pitanja o rasporedu satova, plaćama, dodjeli učenika ili organizaciji rada obrati se administratoru Organizacije.",
  "orgTutorPolicy.s7Tech": "Za tehničke pogreške Platforme (ne radi sinkronizacija kalendara, ne stižu obavijesti) obavijesti administratora Organizacije, koji će kontaktirati tehničku podršku platforme Tutlio.",
  "register.orgPolicyConsent": "Korištenjem naše platforme prihvaćaš",
  "register.orgPolicyLink": "interna pravila",
