  "quiz.info.story.company.title": "Što se promijenilo za tim PRO KLASĖ",
  "quiz.info.story.company.body": "Njihovo rješenje objedinjuje raspored, praćenje satova i prilagođena pravila obračuna naknada u svakodnevnom radu.",
  "quiz.info.story.company.disclosure": "Način rada klijenta",
  "quiz.info.story.school.disclosure": "Način rada klijenta",
  "quiz.info.story.company.brandAlt": "Logotip PRO KLASĖ",
  "quiz.info.story.company.customerName": "PRO KLASĖ",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.info.story.company.customerType": "Tim organizacije za instrukcije",
  "quiz.offer.testimonial.company.role1": "Tim organizacije za instrukcije",
  "quiz.info.story.company.story": "„Prije platforme Tutlio promjene termina, komentari i sati instruktora bili su razbacani po porukama. Sada cijeli tim radi prema istom rasporedu i na kraju mjeseca više ne moramo tražiti ažurirane podatke.”",
  "quiz.info.story.company.proof1": "Raspored tima",
  "quiz.info.story.company.proof2": "Prilagođena pravila obračuna naknada",
  "quiz.info.story.company.proof3": "Nadzor satova",
  "quiz.info.story.company.detail": "„Najveća je razlika bila u prilagodbi odobravanja, nadoknadnih satova i pravila obračuna našem postojećem načinu rada, umjesto nametanja generičkog postupka.”",
  "quiz.info.story.school.title": "Što se promijenilo za VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.body": "Njihov tim povezuje evidencije polaznika, ugovore, obroke plaćanja i računovodstvo u jednom administrativnom postupku.",
  "quiz.info.story.school.brandAlt": "Logotip VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerName": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerType": "Tim školske administracije",
  "quiz.offer.testimonial.school.role1": "Tim školske administracije",
  "quiz.info.story.school.story": "„Željeli smo jedno mjesto na kojem tim može pratiti obitelj od upisa i ugovora do svakog obroka plaćanja. Tutlio nam omogućuje tu povezanost bez održavanja paralelnih tablica.”",
  "quiz.info.story.school.proof1": "Ugovori i potpisi",
  "quiz.info.story.school.proof2": "Rasporedi obročnog plaćanja",
  "quiz.info.story.school.proof3": "Izvoz za računovodstvo",
  "quiz.info.story.school.detail": "„Najjasnije poboljšanje je pregled statusa ugovora, potpisa i plaćanja bez raspitivanja kod više osoba ili provjere zasebnih datoteka.”",
  "quiz.offer.testimonial.school.copy1": "„Najjasnije poboljšanje je pregled statusa ugovora, potpisa i plaćanja bez raspitivanja kod više osoba ili provjere zasebnih datoteka.”",
