  "quiz.offer.testimonials.eyebrow": "Tutlio u svakodnevnom radu",
  "quiz.offer.testimonials.title.solo": "Što primjećuju samostalni instruktori",
  "quiz.offer.testimonials.title.company": "Kako Tutlio podržava organizaciju za instrukcije",
  "quiz.offer.testimonials.title.school": "Kako Tutlio povezuje školsku administraciju",
  "quiz.offer.testimonials.pause": "Pauziraj iskustva korisnika",
  "quiz.offer.testimonials.play": "Pokreni iskustva korisnika",
  "quiz.offer.testimonials.navigation": "Odaberi iskustvo korisnika",
  "quiz.offer.testimonials.goTo": "Prikaži iskustvo korisnika {number}",
  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Instruktor kemije i biologije",
  "quiz.offer.testimonial.solo.copy3": "„Javna stranica i rezervacija putem jedne poveznice pomažu novim učenicima da se brže odluče, a ja više ne moram svakome zasebno slati iste informacije.”",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Instruktor fizike",
  "quiz.offer.testimonial.solo.copy4": "„U kalendaru odmah vidim satove, promjene i statuse plaćanja. Svakodnevna administracija postala je znatno kraća i jasnija.”",
  "quiz.offer.testimonial.company.copy1": "„Promjene termina, komentari instruktora i sati rada prije su stizali u zasebnim porukama. Sada administrativni tim vidi cijelu sliku u jednom rasporedu.”",
  "quiz.offer.testimonial.company.name2": "Neovisni centar za instrukcije",
  "quiz.offer.testimonial.company.role2": "Vlasnik · 8 instruktora",
  "quiz.offer.testimonial.company.copy2": "„Petkom navečer uspoređivao sam kalendar s porukama instruktora prije pripreme obračuna plaća. Uz Tutlio većina tih provjera već je obavljena.”",
  "quiz.offer.testimonial.company.name3": "Studio za jezične instrukcije",
  "quiz.offer.testimonial.company.role3": "Voditelj poslovanja · 14 instruktora",
  "quiz.offer.testimonial.company.copy3": "„Kad se termin sata promijeni, cijeli tim odmah vidi istu promjenu. Imamo manje naknadnih poruka, a roditelji dobivaju mnogo jasnije odgovore.”",
  "quiz.offer.testimonial.company.name4": "Akademija za pripremu ispita",
  "quiz.offer.testimonial.company.role4": "Financijski koordinator · 22 instruktora",
  "quiz.offer.testimonial.company.copy4": "„Naša pravila obračuna naknada instruktora ovise o vrsti sata pa je kraj mjeseca prije zahtijevao mnogo ručnih provjera. Postupak u platformi Tutlio učinio je taj posao znatno mirnijim.”",
  "quiz.offer.testimonial.school.name2": "Neovisna škola u zajednici",
  "quiz.offer.testimonial.school.role2": "Koordinator upisa · 86 polaznika",
  "quiz.offer.testimonial.school.copy2": "„Sezona upisa prije je značila praćenje obrazaca, podataka roditelja i potpisanih ugovora u zasebnim mapama. Sada naš tim može pratiti svaku obitelj na jednom mjestu.”",
  "quiz.offer.testimonial.school.name3": "Centar za izvannastavno učenje",
  "quiz.offer.testimonial.school.role3": "Administrator · 120 polaznika",
  "quiz.offer.testimonial.school.copy3": "„Rasporedi obročnog plaćanja znatno su olakšali praćenje uplata. Prije kontaktiranja roditelja vidim što je dospjelo, bez ručne ponovne izrade popisa.”",
  "quiz.offer.testimonial.school.name4": "Škola umjetničkog obrazovanja",
  "quiz.offer.testimonial.school.role4": "Financijski koordinator · 9 programa",
  "quiz.offer.testimonial.school.copy4": "„Izvoz za računovodstvo sada dolazi iz istih evidencija koje koristimo za ugovore i plaćanja, pa je na kraju mjeseca potrebno mnogo manje ispravaka.”",
  "quiz.offer.savings.eyebrow": "Procijenjeni učinak na utrošak vremena",
