  "landing.custom.sub": "Svaka škola i agencija radi malo drukčije. Kad standardni tijek ne odgovara, prilagodimo Tutlio vašem procesu - obično u tjednima, ne u tromjesečjima. Nekoliko stvari koje smo već izradili za klijente:",
  "landing.custom.ex1Title": "Godišnji ugovori s elektroničkim potpisom",
  "landing.custom.ex1Desc": "Privatnoj školi trebalo je da roditelji godišnje ugovore potpisuju elektronički, plaćaju obročno i da se svaka uplata vidi u izvozu spremnom za knjigovodstvo. Danas se cijeli ciklus odvija unutar Tutlija.",
  "landing.custom.ex2Title": "Pravila naknada i provizija instruktora",
  "landing.custom.ex2Desc": "Agencija svakom instruktoru plaća prema predmetu i vrsti sata, uz proviziju tvrtke. Modelirali smo njihova pravila pa se mjesečni obračuni instruktora i računi stvaraju automatski.",
  "landing.custom.ex3Title": "Ponude roditeljima u jednom kliku",
  "landing.custom.ex3Desc": "Škola je htjela nuditi dodatne satove e-poštom i pustiti roditelje da ih prihvate jednim klikom - bez računa i bez ispisa. Prihvaćanje, naplata i pozivnica na prvi sat sada teku sami.",
  "landing.custom.ex4Title": "Vaš brend na vašoj stranici",
  "landing.custom.ex4Desc": "Organizacija je htjela vlastiti logotip i boje te prijavu ugrađenu u svoju stranicu, tako da učenici i roditelji nikad ne osjete da su je napustili. Tutlio danas radi pod njihovim brendom.",
  "landing.custom.note": "Ništa od toga nije posebno izdanje. Svaka prilagodba postaje dio istog proizvoda koji vaš tim već koristi, uz sva buduća ažuriranja.",
  "landing.custom.cta": "Recite nam kako radite",
  "landing.custom.soloTitle": "Nedostaje li vam nešto?",
  "landing.custom.soloNote": "Redovito razvijamo mogućnosti za pojedine klijente - od jednog pravila plaćanja do cijelog radnog tijeka. Recite nam što bi vam uštedjelo vrijeme.",
  "stats.cancellationPartTutor": "instruktor: {count}",
